// Self-custodial TEST wallet built on Tether's WDK (@tetherto/wdk + @tetherto/wdk-wallet-evm).
// - The seed is generated by WDK, stored only in private/wallet.json (chmod 600, gitignored), never printed.
// - Signing is fully offline: no provider is configured, nonce/fees/chainId come from the last sync.
// - A WDK transaction policy is registered so WDK itself refuses to sign anything except the exact
//   USDT transfer the person confirmed (token, recipient, amount, fee cap). Defence in depth on top of
//   the code checks in safety.js.
import { readFileSync, writeFileSync, existsSync, statSync, mkdirSync } from 'node:fs'
import { dirname } from 'node:path'
import WDK, { PolicyViolationError } from '@tetherto/wdk'
import WalletManagerEvm from '@tetherto/wdk-wallet-evm'
import { Interface, keccak256, getAddress } from 'ethers'

const ERC20 = new Interface(['function transfer(address to, uint256 amount) returns (bool)'])
const WALLET_ID = 'evm-test'
const WRITE_OPS = ['sendTransaction', 'transfer', 'approve', 'sign', 'signTypedData', 'signAuthorization', 'delegate', 'revokeDelegation']

export function walletExists (file) { return existsSync(file) }

/** Create a new test wallet. Returns the address only. Refuses to overwrite. */
export async function createWallet (file) {
  if (existsSync(file)) throw new Error('a wallet already exists; refusing to overwrite it')
  mkdirSync(dirname(file), { recursive: true, mode: 0o700 })
  const seed = WDK.getRandomSeedPhrase(12)
  writeFileSync(file, JSON.stringify({ seed, created: new Date().toISOString(), purpose: 'TEST NETWORKS ONLY' }), { mode: 0o600, flag: 'wx' })
  const w = await openWallet(file, { chainId: 1 })
  const address = await w.address()
  w.dispose()
  return address
}

function readSeed (file) {
  const st = statSync(file)
  // POSIX permission bits. Windows has no such bits (Node reports 0666/0444 there; access is set by the folder's
  // ACLs), so this check cannot apply on Windows: SECURITY.md, "Portable mode".
  if (process.platform !== 'win32' && (st.mode & 0o077) !== 0) throw new Error(`${file} must not be readable by others (chmod 600)`)
  // Never let a parse error quote the file: JSON.parse messages include a piece of the input (here: seed words).
  let seed
  try { seed = JSON.parse(readFileSync(file, 'utf8')).seed } catch { throw new Error('wallet file corrupted') }
  if (typeof seed !== 'string' || !WDK.isValidSeed(seed)) throw new Error('wallet file corrupted')
  return seed
}

/**
 * Open the wallet for signing on one chain.
 * @param {string} file private/wallet.json
 * @param {{chainId:number, maxFeeWei?: bigint}} opts
 */
export async function openWallet (file, { chainId, maxFeeWei = 2_000_000_000_000_000n } = {}) {
  let approved = null // { token, to, amountUnits } set by approve() right after the person confirms
  const wdk = new WDK(readSeed(file))
    .registerWallet(WALLET_ID, WalletManagerEvm, { chainId }) // no provider on purpose: offline signer
    .registerPolicy({
      id: 'sauti-confirmed-transfer-only',
      name: 'Sign only the USDT transfer the person confirmed',
      scope: 'project',
      wallet: WALLET_ID,
      rules: [
        { name: 'allow-reads', operation: '*', action: 'ALLOW', reason: 'read-only calls', conditions: [() => true] },
        { name: 'deny-other-writes', operation: WRITE_OPS, action: 'DENY', reason: 'this app only signs offline USDT transfers', conditions: [() => true] },
        {
          name: 'deny-unconfirmed-sign',
          operation: 'signTransaction',
          action: 'DENY',
          reason: 'transaction does not match the payment the person confirmed',
          conditions: [({ args }) => !matchesApproval(args?.[0], approved, chainId, maxFeeWei)]
        }
      ]
    })
  const account = await wdk.getAccount(WALLET_ID, 0)
  return {
    address: () => account.getAddress(),
    /** Bind the next signature to exactly this transfer (called only after the human confirmation). */
    approve (a) { approved = { token: getAddress(a.token), to: getAddress(a.to), amountUnits: BigInt(a.amountUnits) } },
    /**
     * Build + sign an ERC-20 transfer offline. Returns { raw, hash, tx }.
     * @param {{token:string,to:string,amountUnits:bigint,nonce:number,gasLimit:bigint,maxFeePerGas:bigint,maxPriorityFeePerGas:bigint}} p
     */
    async signTransfer (p) {
      const tx = {
        type: 2,
        chainId,
        to: getAddress(p.token),
        value: 0n,
        data: ERC20.encodeFunctionData('transfer', [getAddress(p.to), BigInt(p.amountUnits)]),
        nonce: p.nonce,
        gasLimit: BigInt(p.gasLimit),
        maxFeePerGas: BigInt(p.maxFeePerGas),
        maxPriorityFeePerGas: BigInt(p.maxPriorityFeePerGas)
      }
      try {
        const raw = await account.signTransaction(tx)
        approved = null // one confirmation = one signature
        return { raw, hash: keccak256(raw), tx }
      } catch (e) {
        if (e instanceof PolicyViolationError) throw new Error(`WDK policy refused to sign: ${e.reason || e.code}`)
        throw e
      }
    },
    /** Try to sign something arbitrary (used by tests to prove the policy blocks it). */
    signRaw: (tx) => account.signTransaction(tx),
    signMessage: (m) => account.sign(m),
    dispose: () => { try { account.dispose?.() } catch {} try { wdk.dispose() } catch {} }
  }
}

function matchesApproval (tx, approved, chainId, maxFeeWei) {
  if (!approved || !tx || typeof tx !== 'object') return false
  try {
    if (Number(tx.chainId) !== Number(chainId)) return false
    if (BigInt(tx.value ?? 0) !== 0n) return false
    if (getAddress(tx.to) !== approved.token) return false
    if (BigInt(tx.gasLimit) * BigInt(tx.maxFeePerGas) > maxFeeWei) return false
    const d = ERC20.decodeFunctionData('transfer', tx.data)
    return getAddress(d[0]) === approved.to && BigInt(d[1]) === approved.amountUnits
  } catch { return false }
}

export { describeRaw } from './txdecode.js'
